package thaumcraft.artifice.grapple;

import com.mojang.authlib.GameProfile;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.animal.Pig;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.common.util.FakePlayer;
import net.minecraftforge.event.entity.EntityJoinLevelEvent;
import net.minecraftforge.event.entity.ProjectileImpactEvent;
import net.minecraftforge.gametest.*;
import net.minecraft.server.level.*;
import thaumcraft.catalog.CatalogModule;
import thaumcraft.catalog.entities.VisualEntitiesModule;
import thaumcraft.equipment.RechargeSupport;

/** Native item/Forge/trajectory trials. Charge, actors and isolated target terrain are supplied fixtures. */
@GameTestHolder("thaumcraft") @PrefixGameTestTemplate(false)
public final class GrappleGameTests {
    private static final AtomicInteger ARENAS=new AtomicInteger();
    private static final TicketType<ChunkPos> TICKET=TicketType.create("thaumcraft_grapple_qa",Comparator.comparingLong(ChunkPos::toLong));
    private GrappleGameTests(){}
    private static final class Trial implements AutoCloseable {
        final GameTestHelper h;final ServerLevel level;final BlockPos pos;final ChunkPos chunk;final FakePlayer p;
        final List<GrappleEntity> shots=new ArrayList<>();final Map<BlockPos,BlockState> blocks=new LinkedHashMap<>();final List<Entity> actors=new ArrayList<>();boolean closed;
        Trial(GameTestHelper h){this.h=h;level=h.getLevel();pos=new BlockPos(4_000_008+128*ARENAS.incrementAndGet(),300,4_000_008);chunk=new ChunkPos(pos);level.getChunkAt(pos);level.getChunkSource().addRegionTicket(TICKET,chunk,2,chunk);p=new FakePlayer(level,new GameProfile(UUID.randomUUID(),"grapple_qa"));p.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+.5);p.setYRot(0);p.setXRot(0);p.setOnGround(true);}
        void set(BlockPos at,BlockState state){blocks.putIfAbsent(at.immutable(),level.getBlockState(at));level.setBlockAndUpdate(at,state);}
        GrappleGunItem gun(){return (GrappleGunItem)CatalogModule.stack("grapple_gun").getItem();}
        ItemStack held(int charge,InteractionHand hand){var s=CatalogModule.stack("grapple_gun");RechargeSupport.addCharge(s,p,charge);p.setItemInHand(hand,s);return s;}
        GrappleEntity fire(InteractionHand hand,Consumer<EntityJoinLevelEvent> extra){int before=shots.size();Consumer<EntityJoinLevelEvent> listener=e->{if(e.getLevel()==level&&e.getEntity() instanceof GrappleEntity g&&g.getOwner()==p){shots.add(g);extra.accept(e);}};MinecraftForge.EVENT_BUS.addListener(listener);try{h.assertTrue(gun().use(level,p,hand).getResult()==InteractionResult.SUCCESS,"Original use did not return SUCCESS");}finally{MinecraftForge.EVENT_BUS.unregister(listener);}return shots.size()==before?null:shots.get(shots.size()-1);}
        GrappleEntity fire(){return fire(InteractionHand.MAIN_HAND,e->{});}
        @Override public void close(){if(closed)return;closed=true;for(var g:shots)g.discard();for(var a:actors)a.discard();var rows=new ArrayList<>(blocks.entrySet());Collections.reverse(rows);for(var row:rows)level.setBlockAndUpdate(row.getKey(),row.getValue());level.getChunkSource().removeRegionTicket(TICKET,chunk,2,chunk);}
    }
    private static void run(GameTestHelper h,Consumer<Trial> action){var f=new Trial(h);h.startSequence().thenWaitUntil(()->h.assertTrue(f.level.areEntitiesLoaded(f.chunk.toLong())&&f.level.getChunkSource().isPositionTicking(f.chunk.toLong()),"Owned grapple chunk is not natively ticking yet"))
        .thenExecute(()->{try{action.accept(f);}finally{f.close();}}).thenSucceed();h.runAtTickTime(298,()->{if(!f.closed){f.close();h.fail("Bounded grapple arena preparation timed out");}});}
    @GameTest(template="empty",timeoutTicks=300) public static void originalCapacityRarityAndNoDurabilityAmmoOrCreativeChargeExemption(GameTestHelper h){run(h,f->{var s=f.held(100,InteractionHand.MAIN_HAND);h.assertTrue(s.getMaxStackSize()==1&&s.getMaxDamage()==0&&s.getRarity()==Rarity.UNCOMMON&&f.gun().getMaxCharge(s,f.p)==100,"Original100charge/uncommon/non-damageable tool changed");for(var mode:new GameType[]{GameType.SURVIVAL,GameType.CREATIVE}){f.p.setGameMode(mode);int charge=RechargeSupport.getCharge(s);var g=f.fire();h.assertTrue(g!=null&&!g.isRemoved()&&RechargeSupport.getCharge(s)==charge-1&&s.getCount()==1,"Accepted shot was free/consumed ammo or gun");}});}
    @GameTest(template="empty",timeoutTicks=300) public static void emptyRightClickSucceedsWithoutCreatingHookOrManufacturingCharge(GameTestHelper h){run(h,f->{var s=f.held(0,InteractionHand.MAIN_HAND);var before=s.copy();h.assertTrue(f.fire()==null&&ItemStack.matches(s,before),"Empty use created hook or charge/NBT");});}
    @GameTest(template="empty",timeoutTicks=300) public static void offhandPaysItsOwnPhysicalGunAndRetainsOriginalHand(GameTestHelper h){run(h,f->{var main=f.held(9,InteractionHand.MAIN_HAND);var off=f.held(5,InteractionHand.OFF_HAND);var g=f.fire(InteractionHand.OFF_HAND,e->{});h.assertTrue(g.hand()==InteractionHand.OFF_HAND&&RechargeSupport.getCharge(main)==9&&RechargeSupport.getCharge(off)==4&&off.getTag().getByte("loaded")==1,"Offhand shot paid the wrong tool or lost hand");});}
    @GameTest(template="empty",timeoutTicks=300) public static void canceledSpawnRestoresExactChargeAndTagAndCannotExecuteProvisionalHook(GameTestHelper h){run(h,f->{var s=f.held(3,InteractionHand.MAIN_HAND);s.getOrCreateTag().putString("custom","retained");var before=s.copy();var g=f.fire(InteractionHand.MAIN_HAND,e->{((GrappleEntity)e.getEntity()).tick();h.assertTrue(GrappleModule.active(f.level,f.p)==null,"Provisional unpaid hook registered or pulled");e.setCanceled(true);});h.assertTrue(g.isRemoved()&&ItemStack.matches(before,s)&&GrappleModule.active(f.level,f.p)==null,"Canceled native spawn spent charge/loaded NBT");});}
    @GameTest(template="empty",timeoutTicks=300) public static void spawnCallbackReentryCannotSpendOrSpawnTheSameShotTwice(GameTestHelper h){run(h,f->{var s=f.held(3,InteractionHand.MAIN_HAND);var g=f.fire(InteractionHand.MAIN_HAND,e->f.gun().use(f.level,f.p,InteractionHand.MAIN_HAND));h.assertTrue(f.shots.size()==1&&!g.isRemoved()&&RechargeSupport.getCharge(s)==2,"Reentrant spawn repeated native charge payment");});}
    @GameTest(template="empty",timeoutTicks=300) public static void replacementHandOwnedByCallbackIsNeitherRestoredNorUsedAsPayment(GameTestHelper h){run(h,f->{var s=f.held(3,InteractionHand.MAIN_HAND);var other=new ItemStack(Items.EMERALD,7);var g=f.fire(InteractionHand.MAIN_HAND,e->f.p.setItemInHand(InteractionHand.MAIN_HAND,other));h.assertTrue(g.isRemoved()&&f.p.getMainHandItem()==other&&other.getCount()==7&&RechargeSupport.getCharge(s)==3,"Foreign hand changed or exact unchanged gun lost its canceled-shot refund");});}
    @GameTest(template="empty",timeoutTicks=300) public static void canceledSpawnRefundsUnchangedPhysicalGunAfterCallbackMovesItToAnotherSlot(GameTestHelper h){run(h,f->{var s=f.held(3,InteractionHand.MAIN_HAND);s.getOrCreateTag().putString("original","retained");var before=s.copy();var g=f.fire(InteractionHand.MAIN_HAND,e->{f.p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);f.p.getInventory().setItem(9,s);e.setCanceled(true);});h.assertTrue(g.isRemoved()&&f.p.getMainHandItem().isEmpty()&&f.p.getInventory().getItem(9)==s&&ItemStack.matches(s,before),"Canceled native spawn lost moved physical gun charge/tag");});}
    @GameTest(template="empty",timeoutTicks=300) public static void explicitOwnerClearReleasesMapAndCannotReviveCachedNativeUuidOrSavedOwner(GameTestHelper h){run(h,f->{f.held(3,InteractionHand.MAIN_HAND);var g=f.fire();f.level.tickNonPassenger(g);g.setOwner(null);var tag=new CompoundTag();g.saveWithoutId(tag);h.assertTrue(g.getOwner()==null&&GrappleModule.active(f.level,f.p)==null&&!tag.hasUUID("Owner"),"Explicit owner clear retained live map or native cached UUID");g.load(tag);h.assertTrue(g.getOwner()==null&&GrappleModule.active(f.level,f.p)==null,"Same-object native load revived cleared cached owner");f.level.tickNonPassenger(g);h.assertTrue(g.isRemoved(),"Cleared owner resumed a paid hook");});}
    @GameTest(template="empty",timeoutTicks=300) public static void nativeImpactCallbackOwnerChangeNeverPullsPreviouslyCachedActor(GameTestHelper h){run(h,f->{for(int mode=0;mode<2;mode++){f.held(3,InteractionHand.MAIN_HAND);f.p.setDeltaMovement(Vec3.ZERO);for(int y=0;y<4;y++)f.set(f.pos.offset(0,y,3),Blocks.STONE.defaultBlockState());var pig=EntityType.PIG.create(f.level);pig.setNoAi(true);pig.setNoGravity(true);pig.setPos(f.p.position().add(10,0,0));f.actors.add(pig);f.level.addFreshEntity(pig);var g=f.fire();int selected=mode;int[] impacts={0};Consumer<ProjectileImpactEvent> change=e->{if(e.getProjectile()==g){impacts[0]++;g.setOwner(selected==0?null:pig);}};MinecraftForge.EVENT_BUS.addListener(change);try{for(int i=0;i<5&&impacts[0]==0;i++)f.level.tickNonPassenger(g);}finally{MinecraftForge.EVENT_BUS.unregister(change);}h.assertTrue(impacts[0]>0&&f.p.getDeltaMovement().equals(Vec3.ZERO)&&GrappleModule.active(f.level,f.p)==null,"Native impact callback pulled or rebound stale owner");g.discard();}});}
    @GameTest(template="empty",timeoutTicks=300) public static void literalMuzzleZUsesLookYAndVelocityInheritsAirborneOwnerMotion(GameTestHelper h){run(h,f->{f.held(3,InteractionHand.MAIN_HAND);f.p.setXRot(30);f.p.setYRot(0);f.p.setOnGround(false);f.p.setDeltaMovement(.2,.3,.4);var g=f.fire();var look=f.p.getLookAngle();float a=(-.5F)/180F*3.141593F;h.assertTrue(Math.abs(g.getZ()-(f.p.getZ()-net.minecraft.util.Mth.sin(a)*.3F+look.y))<1e-9&&Math.abs(g.getX()-(f.p.getX()-net.minecraft.util.Mth.cos(a)*.2F+look.x))<1e-9,"Released lookY muzzle-Z source quirk changed");h.assertTrue(Math.abs(g.getY()-(f.p.getEyeY()-.10000000149011612))<1e-9&&g.getDeltaMovement().z>.4&&g.getDeltaMovement().x>.19,"Legacy owner velocity inheritance/eye start changed");});}
    @GameTest(template="empty",timeoutTicks=300) public static void nativeBlockImpactAnchorsWithoutBreakingOrConsumingMoreCharge(GameTestHelper h){run(h,f->{f.held(3,InteractionHand.MAIN_HAND);for(int x=-2;x<=2;x++)for(int y=-1;y<=3;y++)f.set(f.pos.offset(x,y,5),Blocks.STONE.defaultBlockState());var g=f.fire();for(int i=0;i<8&&!g.pulling();i++)f.level.tickNonPassenger(g);h.assertTrue(g.pulling()&&!g.isRemoved()&&g.getDeltaMovement().equals(Vec3.ZERO)&&f.level.getBlockState(f.pos.south(5)).is(Blocks.STONE)&&RechargeSupport.getCharge(f.p.getMainHandItem())==2,"Native block anchor broke block or billed pull ticks");});}
    @GameTest(template="empty",timeoutTicks=300) public static void entityImpactAnchorsAtEntityPositionWithoutDamageOrFollowingTarget(GameTestHelper h){run(h,f->{f.held(3,InteractionHand.MAIN_HAND);var pig=EntityType.PIG.create(f.level);pig.setNoAi(true);pig.setNoGravity(true);pig.setPos(f.p.getX(),f.p.getY()+1,f.p.getZ()+4);f.actors.add(pig);f.level.addFreshEntity(pig);float hp=pig.getHealth();var g=f.fire();for(int i=0;i<6&&!g.pulling();i++)f.level.tickNonPassenger(g);h.assertTrue(g.pulling()&&g.position().equals(pig.position())&&pig.getHealth()==hp,"Entity hit did not retain original no-damage entity-position anchor");var anchor=g.position();pig.setPos(pig.position().add(3,0,0));f.level.tickNonPassenger(g);h.assertTrue(g.position().equals(anchor),"Hook invented a moving entity tether");});}
    @GameTest(template="empty",timeoutTicks=300) public static void canceledProjectileImpactKeepsHookFlyingAndTargetUntouched(GameTestHelper h){run(h,f->{f.held(3,InteractionHand.MAIN_HAND);for(int y=0;y<4;y++)f.set(f.pos.offset(0,y,3),Blocks.STONE.defaultBlockState());var g=f.fire();int[] impacts={0};Consumer<ProjectileImpactEvent> veto=e->{if(e.getProjectile()==g){impacts[0]++;e.setCanceled(true);}};MinecraftForge.EVENT_BUS.addListener(veto);try{for(int i=0;i<5;i++)f.level.tickNonPassenger(g);}finally{MinecraftForge.EVENT_BUS.unregister(veto);}h.assertTrue(impacts[0]>0&&!g.pulling()&&!g.isRemoved(),"Forge impact veto still anchored or killed paid hook");});}
    @GameTest(template="empty",timeoutTicks=300) public static void firstPullAddsOneBoostThenUsesOriginalCappedAccelerationAndResetsFall(GameTestHelper h){run(h,f->{f.held(3,InteractionHand.MAIN_HAND);var g=f.fire();g.onHit(new net.minecraft.world.phys.BlockHitResult(f.p.position().add(0,8,0),Direction.DOWN,f.pos.above(8),false));f.p.setDeltaMovement(Vec3.ZERO);f.p.fallDistance=14;f.level.tickNonPassenger(g);h.assertTrue(Math.abs(f.p.getDeltaMovement().y-(.2+.033+.4000000059604645))<1e-8&&f.p.fallDistance==0&&g.boosted(),"Original distance8 force/first boost/fall reset changed");f.p.setDeltaMovement(Vec3.ZERO);f.level.tickNonPassenger(g);h.assertTrue(Math.abs(f.p.getDeltaMovement().y-.233)<1e-8,"Initial boost repeated on later pull");});}
    @GameTest(template="empty",timeoutTicks=300) public static void sneakDoesNotCancelFlightButReleasesPullWithoutExtraCost(GameTestHelper h){run(h,f->{var s=f.held(3,InteractionHand.MAIN_HAND);f.p.setXRot(-90);f.p.setShiftKeyDown(true);var g=f.fire();f.level.tickNonPassenger(g);h.assertTrue(!g.isRemoved()&&!g.pulling(),"Sneak incorrectly canceled airborne hook");g.onHit(new net.minecraft.world.phys.BlockHitResult(f.p.position().add(0,5,0),Direction.DOWN,f.pos.above(5),false));f.level.tickNonPassenger(g);h.assertTrue(g.isRemoved()&&RechargeSupport.getCharge(s)==2&&GrappleModule.active(f.level,f.p)==null,"Sneak did not release anchored hook for free");});}
    @GameTest(template="empty",timeoutTicks=300) public static void flyingHookSurvivesThirtyUpdatesAndExpiresOnThirtyFirst(GameTestHelper h){run(h,f->{f.held(3,InteractionHand.MAIN_HAND);f.p.setXRot(-90);var g=f.fire();for(int i=0;i<30;i++)f.level.tickNonPassenger(g);h.assertTrue(!g.isRemoved()&&g.tickCount==30,"Legacy strict greater-than30 flight limit changed");f.level.tickNonPassenger(g);h.assertTrue(g.isRemoved()&&GrappleModule.active(f.level,f.p)==null,"Flying hook exceeded native31-update lifetime");});}
    @GameTest(template="empty",timeoutTicks=300) public static void repeatFireReplacesPriorOwnerHookOnFirstUpdateAndCleanupCannotClaimNewHook(GameTestHelper h){run(h,f->{var s=f.held(5,InteractionHand.MAIN_HAND);f.p.setXRot(-90);var a=f.fire();f.level.tickNonPassenger(a);var b=f.fire();h.assertTrue(!a.isRemoved()&&GrappleModule.active(f.level,f.p)==a,"Prior hook was removed before replacement first update");f.level.tickNonPassenger(b);h.assertTrue(a.isRemoved()&&GrappleModule.active(f.level,f.p)==b&&RechargeSupport.getCharge(s)==3,"Refire did not replace exact prior hook at original timing");a.discard();h.assertTrue(GrappleModule.active(f.level,f.p)==b,"Stale removal erased new owner's hook");});}
    @GameTest(template="empty",timeoutTicks=300) public static void itemLoadedResetKeepsChargeAndReequipOnlyTracksReleasedLoadedTransition(GameTestHelper h){run(h,f->{var s=f.held(3,InteractionHand.MAIN_HAND);s.getOrCreateTag().putByte("loaded",(byte)1);var old=s.copy();f.gun().inventoryTick(s,f.level,f.p,0,false);h.assertTrue(s.getTag().getByte("loaded")==0&&RechargeSupport.getCharge(s)==3&&f.gun().shouldCauseReequipAnimation(old,s,false),"Original loaded-only reset/reequip changed");var charge=s.copy();RechargeSupport.consumeCharge(charge,f.p,1);h.assertTrue(!f.gun().shouldCauseReequipAnimation(s,charge,true),"Charge-only NBT change invented an equip animation");});}
    @GameTest(template="empty",timeoutTicks=300) public static void originalTransientPullHandAndBoostAreNotRestoredFromEntitySave(GameTestHelper h){run(h,f->{f.held(3,InteractionHand.OFF_HAND);var g=f.fire(InteractionHand.OFF_HAND,e->{});g.onHit(new net.minecraft.world.phys.BlockHitResult(f.p.position().add(0,5,0),Direction.DOWN,f.pos.above(5),false));f.level.tickNonPassenger(g);var tag=new CompoundTag();g.saveWithoutId(tag);var copy=VisualEntitiesModule.GRAPPLE.get().create(f.level);copy.load(tag);h.assertTrue(!copy.pulling()&&!copy.boosted()&&copy.hand()==InteractionHand.MAIN_HAND&&copy.amplitude()==0&&!tag.contains("Pulling")&&!tag.contains("Hand"),"Original transient grapple state incorrectly persisted");copy.discard();});}
}
